    2: `<div class="center" style="max-width:460px;margin:auto"><h3>${t('verifyOtp')}</h3><p class="muted">${t('otpManagerText')}</p><div class="otp">${[1, 2, 3, 4, 5, 6].map(n => `<input maxlength="1" value="${n}">`).join('')}</div><div class="mt"><button class="link">${t('resendIn')} 00:42</button></div></div>`,
