/* ---------- report units (visit × clinical group) ---------- */
function unitsOfVisit(v) {
  const map = {};
  v.lines.filter(l => l.status !== 'Cancelled').forEach(l => {
    const s = svcById(l.service); if (!s) return; const svcs = s.type === 'Package' ? s.members.map(m => svcById(m.service)) : [s];
    svcs.forEach(ss => { if (!ss || ss.type === 'Additional') return; const key = ss.printAlone ? `g${ss.group}-s${ss.id}` : `g${ss.group}`; const u = map[key] = map[key] || { key: `${v.id}:${key}`, visit: v, group: ss.group, services: [], printAlone: ss.printAlone }; u.services.push({ service: ss, line: l }); });
  });
  Object.values(map).forEach(u => { const ids = u.services.map(x => x.service.id); u.results = DB.results.filter(r => r.visit === v.id && ids.includes(r.service)); u.reserved = u.services.every(x => x.line.status === 'Reserved'); u.status = u.results.length ? SCREEN_ORDER[Math.min(...u.results.map(r => stIdx(r.status)))] : 'Ordered'; u.printed = u.results.length > 0 && u.results.every(r => r.printed); u.samples = v.samples.filter(s => s.services.some(id => ids.includes(id))); u.received = u.samples.length > 0 && u.samples.every(s => s.status === 'Received'); u.abnormal = u.results.some(r => r.flag && r.flag !== 'N'); u.delta = u.results.some(r => r.delta); u.manual = !u.results.some(r => r.analyzer); u.analyzers = [...new Set(u.results.map(r => r.analyzer).filter(Boolean))]; });
  return Object.values(map);
}
const reportUnitsAll = () => DB.visits.flatMap(unitsOfVisit);
function unitColor(u) { const s = u.status, p = u.printed; if (u.reserved) return ['#FFF3B0', t('uc_reservedNP')]; if (s === 'Ordered') return p ? ['#1D3F8F', t('uc_incP')] : ['#FFD6E0', t('uc_incNP')]; if (s === 'Complete') return p ? ['#8E6CD6', t('uc_compP')] : ['#F28B82', t('uc_compNP')]; if (s === 'Reviewed') return p ? ['#F6B5C5', t('uc_revP')] : ['#C9F0D5', t('uc_revNP')]; if (s === 'Verified') return p ? ['#5FC48F', t('uc_verP')] : ['#2B2B2B', t('uc_verNP')]; return ['#5FC48F', t('uc_verP')]; }

/* ---------- dashboard ---------- */
App.screens.home = () => {
  const vToday = DB.visits.filter(v => isToday(v.date)); const payToday = DB.visits.flatMap(v => v.payments).filter(p => isToday(p.date)).reduce((s, p) => s + p.amount, 0);
  const recv = DB.visits.flatMap(v => v.samples).filter(s => s.events.some(e => e.status === 'Received' && isToday(e.time))).length; const pending = DB.results.filter(r => r.status === 'Ordered').length; const backlog = DB.results.filter(r => ['Complete', 'Reviewed'].includes(r.status)).length;
  const delayed = worklistRows({}).filter(r => r.delay > 0 && stIdx(r.status) < 3); const rejected = DB.visits.flatMap(v => v.samples).filter(s => s.status === 'Rejected').length;
  return pageHead(t('dashboard'), `${esc(L(App.branch))} · ${fmtDate(NOW())}`, `<button class="btn" onclick="renderMain()">${ic('refresh')} ${t('refresh')}</button>`) +
    `<div class="kpis">${kpi(t('registrations'), vToday.length, t('today'), 'clipboard')}${kpi(t('collectedToday'), money(payToday), t('today'), 'dollar', 'ok')}${R1 ? '' : kpi(t('samplesReceived'), recv, t('today'), 'tube')}${kpi(t('pendingResults'), pending, t('awaitingEntry'), 'flask', 'warn')}${kpi(t('unverifiedBacklog'), backlog, t('awaitingSignoff'), 'checkcircle', 'warn')}${kpi(t('delayedTests'), delayed.length, t('pastTurnaround'), 'clock', delayed.length ? 'bad' : 'ok')}${R1 ? '' : kpi(t('rejectedSamples'), rejected, t('today'), 'slash', rejected ? 'bad' : 'ok')}${kpi(t('walletBalance'), money(App.wallet), DB.tenant.plan, 'wallet')}</div>
<div class="dash-grid">${card({ title: t('registrationsLast7'), body: barChart([29, 35, 31, 46, 38, 51, vToday.length + 40], ['Th', 'Fr', 'Sa', 'Su', 'Mo', 'Tu', 'We']) })}${card({ title: t('quickActions'), body: `<div class="module-grid">${(R1 ? [['registration', 'userplus'], ['searchRegistrations', 'search'], ['resultsByAccession', 'flask'], ['worklist', 'list'], ['payments', 'dollar'], ['priceQuery', 'tag']] : [['registration', 'userplus'], ['collection', 'scan'], ['resultsByAccession', 'flask'], ['workQueue', 'layers'], ['payments', 'dollar'], ['cashClosing', 'checkcircle']]).map(([k, i]) => `<button class="btn" style="justify-content:flex-start" onclick="navigate('${k}')">${ic(i)} ${t(k)}</button>`).join('')}</div>` })}</div>
<div class="grid2">${card({ title: t('delayedTests'), sub: t('delayedSub'), flush: true, body: grid({ cols: [{ k: 'acc', l: 'accession', f: r => `<b>${r.acc}</b>` }, { k: 'patient', l: 'patient' }, { k: 'test', l: 'test' }, { k: 'delay', l: 'delay', f: r => badge(fmtDur(r.delay), 'bad') }, { k: 'status', l: 'status', f: r => sb(r.status) }], rows: delayed.slice(0, 6), nofoot: true }) })}${card({ title: t('recentActivity'), body: `<div class="activity">${DB.auditLog.slice(0, 6).map(a => `<div class="arow"><div class="aico">${ic('activity', 14)}</div><div><b>${esc(a.action)}</b><p>${esc(a.entity)} · ${esc(a.detail)} · ${esc(a.user)}</p></div><time>${fmtDT(a.time).slice(11)}</time></div>`).join('')}</div>` })}</div>`;
};

/* ---------- registration ---------- */
const Reg = { patient: {}, isNew: true, visit: { payer: 1, tier: 1, locType: 'Out Patient' }, lines: [], prep: {}, discount: 0, discountPct: 0, discountReason: '', booking: null, editVisit: null, payment: { method: 'Cash', amount: null, ref: '' } };
function regReset() { Object.assign(Reg, { patient: {}, isNew: true, visit: { payer: 1, tier: 1, locType: 'Out Patient', branch: App.branch.id }, lines: [], prep: {}, discount: 0, discountPct: 0, discountReason: '', booking: null, editVisit: null, payment: { method: 'Cash', amount: null, ref: '' } }); }
const regDue = () => Math.max(0, Reg.lines.filter(l => l.status !== 'Cancelled').reduce((s, l) => s + l.patient - (l.discount || 0), 0) - (Reg.discount || 0));
